HEADER = "// Generated by .github/scripts/embed_component_migration.py; edit the development templates and run --write.\n"


def csharp_string(value):
    return json.dumps(value, ensure_ascii=False)


def render_rule(component):
    fields = ", ".join(csharp_string(value) for value in component["fields"])
    return ("            new Rule { Name = " + csharp_string(component["name"]) + ", Label = "
            + csharp_string(component["label"]) + ", CanonicalGuid = " + csharp_string(component["guid"])
            + ", Strong = " + str(component["strong"]).lower() + ",\n"
            + "                Fields = new[] { " + fields + " } },")


def owner_tests(owner):
    types = ", ".join(csharp_string(COMPONENTS[key]["name"]) for key in owner["types"])
    peer = COMPONENTS[owner["peer"]]
    return f'''        [Test]
        public void CatalogAndProjectMenuBelongToThisPlugin()
        {{
            Assert.That(MigrationEngine.GetTargetTypes().Select(target => target.TypeName),
                Is.EquivalentTo(new[] {{ {types} }}));
            var menu = (MenuItem)Attribute.GetCustomAttribute(typeof(ComponentReferenceMigrationWindow)
                .GetMethod("Open", BindingFlags.Public | BindingFlags.Static), typeof(MenuItem));
            Assert.That(menu.menuItem, Is.EqualTo("Assets/UnityBox/{owner['display']}/Repair Component References"));
        }}

        [Test]
        public void PeerPluginSchemaIsReportedWithoutOfferingAnOwnerTypeMapping()
        {{
            string path = Prefab({csharp_string(peer['fixture'])});
            byte[] original = File.ReadAllBytes(path);
            var plan = MigrationEngine.Scan(new[] {{ path }});
            Assert.That(plan.Entries.Single().Status, Is.EqualTo(MigrationStatus.Skipped));
            Assert.That(plan.Entries.Single().TypeName, Is.Empty);
            Assert.That(plan.Entries.Single().CandidateTypes, Is.Empty);
            Assert.That(MigrationEngine.Apply(plan).ChangedAssets, Is.Empty);
            Assert.That(File.ReadAllBytes(path), Is.EqualTo(original));
        }}

        [Test]
        public void ExplicitOverridesCannotSelectAnotherPluginsComponentType()
        {{
            string path = Prefab();
            byte[] original = File.ReadAllBytes(path);
            Assert.Throws<ArgumentException>(() => MigrationEngine.Scan(new[] {{ path }},
                new Dictionary<string, string> {{ {{ Legacy, {csharp_string(peer['name'])} }} }}));
            Assert.That(File.ReadAllBytes(path), Is.EqualTo(original));
        }}

'''


def rendered_files():
    template_root = Path(__file__).with_name("templates") / "component_migration"
    templates = {path.name: path.read_text(encoding="utf-8") for path in template_root.glob("*.cs.in")}
    files = {}
    for owner in OWNERS:
        root = Path("Assets/UnityBox") / owner["name"]
        primary = COMPONENTS[owner["primary"]]
        substitutions = {
            "__NAMESPACE__": "UnityBox." + owner["name"] + ".ComponentMigration",
            "__OWNER__": owner["name"], "__DISPLAY__": owner["display"], "__ABBR__": owner["abbr"],
            "__RULES__": "\n".join(render_rule(COMPONENTS[key]) for key in owner["types"]),
            "__MENU__": "Assets/UnityBox/" + owner["display"] + "/Repair Component References",
            "__TITLE__": owner["abbr"] + " Component References", "__PRIMARY__": primary["name"],
            "__PRIMARY_FIELDS__": csharp_string(primary["fixture"]),
            "__OWNER_TESTS__": owner_tests(owner),
            "__WEAK_CONSTANT__": ('        private const string Part = "' + COMPONENTS["Part"]["name"] + '";') if owner["name"] == "AdvancedCostumeController" else "",
            "__WEAK_TESTS__": templates["WeakTests.cs.in"] if owner["name"] == "AdvancedCostumeController" else "",
            "__WEAK_MESSAGE__": "候选 ACC Part Group Marker（Mode / GroupName）；需要一次 GUID 类型映射。 / Candidate only: choose a GUID-to-type mapping before migrating.",
            "__MAPPING_HELP__": "Mode / GroupName 等通用字段不会被自动猜为 ACC 组件。" if owner["name"] == "AdvancedCostumeController" else "其它插件的未知引用不会作为本插件候选。",
        }
        destinations = [("MigrationEngine.cs.in", root / owner["editor"] / "MigrationEngine.cs"),
                        ("Window.cs.in", root / owner["editor"] / "ComponentReferenceMigrationWindow.cs"),
                        ("Tests.cs.in", root / owner["tests"] / "ComponentMigrationTests.cs")]
        if owner["name"] == "AvatarSecuritySystem":
            destinations.append(("Performance.cs.in", root / owner["tests"] / "ComponentMigrationPerformanceTests.cs"))
        for template, path in destinations:
            text = templates[template]
            for key, value in substitutions.items():
                text = text.replace(key, value)
            unresolved = re.findall(r"__[A-Z_]+__", text)
            if unresolved:
                raise ValueError(f"Unresolved template tokens in {path}: {unresolved}")
            files[path] = HEADER + text
    return files


def new_metadata(path, folder=False):
    guid = uuid.uuid5(uuid.NAMESPACE_URL, "https://github.com/SeaLoong/UnityBox/" + path.as_posix()).hex
    text = "fileFormatVersion: 2\nguid: " + guid + "\n"
    if folder:
        text += "folderAsset: yes\nDefaultImporter:\n  externalObjects: {}\n  userData:\n  assetBundleName:\n  assetBundleVariant:\n"
    return text


def metadata_paths(files):
    folders = {path.parent for path in files}
    return {Path(str(path) + ".meta"): False for path in files} | {Path(str(path) + ".meta"): True for path in folders}


def synchronize(repo, check=True):
    repo = Path(repo).resolve()
    files = rendered_files()
    metadata = metadata_paths(files)
    problems = []
    for relative, text in files.items():
        path = repo / relative
        if check:
            if not path.is_file() or path.read_bytes() != text.encode("utf-8"):
                problems.append("Generated source differs: " + relative.as_posix())
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding="utf-8", newline="\n")
    guids = {}
    for relative, folder in metadata.items():
        path = repo / relative
        if not path.is_file():
            if check:
                problems.append("Missing generated asset metadata: " + relative.as_posix())
                continue
            path.write_text(new_metadata(Path(str(relative).removesuffix(".meta")), folder), encoding="utf-8")
        text = path.read_text(encoding="utf-8")
        match = re.search(r"(?m)^guid: ([a-fA-F0-9]{32})\s*$", text)
        if not match:
            problems.append("Invalid generated asset GUID: " + relative.as_posix())
            continue
        guid = match[1].lower()
        if guid in guids:
            problems.append("Duplicate generated asset GUID: " + guids[guid] + " and " + relative.as_posix())
        guids[guid] = relative.as_posix()
        if folder and not re.search(r"(?m)^folderAsset: yes\s*$", text):
            problems.append("Generated folder metadata is not a folder: " + relative.as_posix())
    return problems


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", type=Path, default=Path(__file__).resolve().parents[2])
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--check", action="store_true", help="Check synchronized sources and metadata without modifying them (default)")
    mode.add_argument("--write", action="store_true", help="Regenerate sources and create missing metadata; retain all existing metadata")
    args = parser.parse_args(argv)
    problems = synchronize(args.repo, check=not args.write)
    if problems:
        for problem in problems:
            print(problem)
        return 1
    print(f"Owner-scoped component migration sources synchronized: {len(OWNERS)} plugins, {len(rendered_files())} C# files.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
